191	// readClaudeTuiModelDiscoveryViaPTY spawns a PTY session against the claude CLI,
192	// sends the /model command, and parses the output to extract available models.
193	// Per the no-static-fallback principle, returns ErrModelDiscoveryEvidenceMissing
194	// if the PTY fails or yields no models; never returns a partial or empty snapshot.
195	func readClaudeTuiModelDiscoveryViaPTY(ctx context.Context, timeout time.Duration) (harnesses.ModelDiscoverySnapshot, error) {
196		// Variable to capture the snapshot once discovery succeeds.
197		var snapshot harnesses.ModelDiscoverySnapshot
198		var discoveryErr error
199	
200		_, err := ptyquota.Run(ctx, ptyquota.Config{
201			HarnessName:  "claude-tui",
202			Binary:       "claude",
203			Args:         nil,
204			Workdir:      "",
205			Env:          nil,
206			Command:      "/model\r",
207			ReadyMarkers: []string{"❯", "> "},
208			DoneWhen:     claudeTuiModelDiscoveryComplete,
209			Timeout:      timeout,
210			Size:         session.Size{Rows: 50, Cols: 220},
211			Discovery: func(text string) (cassette.DiscoveryRecord, error) {
212				models := ParseClaudeTuiModels(text)
213				if len(models) == 0 {
214					discoveryErr = harnesses.ErrModelDiscoveryEvidenceMissing
215					return cassette.DiscoveryRecord{}, fmt.Errorf("no models found in /model output")
216				}
217				// Build snapshot only after confirming we have models.
218				snapshot.CapturedAt = time.Now().UTC()
219				snapshot.FreshnessWindow = (24 * time.Hour).String()
220				snapshot.Source = "pty"
221				snapshot.Models = models
222				snapshot.ReasoningLevels = ParseClaudeTuiReasoningLevels(text)
223				return discoveryRecordFromSnapshot(snapshot), nil
224			},
225		})
226		if err != nil {
227			if discoveryErr != nil {
228				return emptyModelSnapshot, discoveryErr
229			}
230			return emptyModelSnapshot, fmt.Errorf("model discovery PTY: %w", err)
231		}
232		if len(snapshot.Models) == 0 {
233			return emptyModelSnapshot, harnesses.ErrModelDiscoveryEvidenceMissing
234		}
235		return snapshot, nil
236	}
