288	func discoveryRecordFromSnapshot(snapshot harnesses.ModelDiscoverySnapshot) cassette.DiscoveryRecord {
289		return cassette.DiscoveryRecord{
290			Source:            snapshot.Source,
291			Status:            string(ptyquota.StatusOK),
292			Models:            append([]string(nil), snapshot.Models...),
293			ReasoningLevels:   append([]string(nil), snapshot.ReasoningLevels...),
294			CapturedAt:        snapshot.CapturedAt.UTC().Format(time.RFC3339),
295			FreshnessWindow:   snapshot.FreshnessWindow,
296			StalenessBehavior: "stale model discovery evidence requires authenticated PTY refresh before capability promotion",
297			Metadata:          map[string]any{"detail": snapshot.Detail},
298		}
299	}
300	
301	func uniqueMatches(values []string) []string {
302		out := make([]string, 0, len(values))
303		for _, value := range values {
304			out = appendUniqueString(out, value)
305		}
306		return out
307	}
308	
309	func appendUniqueString(values []string, value string) []string {
310		value = strings.TrimSpace(value)
311		if value == "" {
312			return values
313		}
314		for _, existing := range values {
315			if existing == value {
316				return values
317			}
318		}
319		return append(values, value)
320	}
